import type { Locale } from "@/i18n/config";
import { expandedSkillSchema, type ExpandedSkill } from "@/lib/learning/expanded-schemas";

const l = (es: string, en: string) => ({ "es-CL": es, en });
const validatedIds = new Set([
  "competitive-advantage", "pricing-strategy", "financial-statements", "economics.unit-economics", "contribution-margin", "elasticity", "marginal-cost", "segmentation", "process-design", "decision-rights", "probability", "experimentation", "ai.model-landscape", "ai-evaluation-basics", "ai-inference-economics", "ai-pricing", "ai-capability-feature-product", "ai-copilot-agent", "agent-workflow-decomposition",
]);
const review = (id: string) => ({ reviewStatus: validatedIds.has(id) ? "validated" as const : "reviewed" as const, review: { reviewedAt: "2026-08-09", reviewer: "Skala editorial", references: [id.startsWith("ai") || id.startsWith("agent") ? "Skala AI curriculum synthesis v0.2" : "Skala Business Core synthesis v0.2"], freshness: id.startsWith("ai") || id.startsWith("agent") ? "time-sensitive" as const : "stable" as const } });
const skill = (id: string, misconception: ReturnType<typeof l>, principle: ReturnType<typeof l>, boundary: ReturnType<typeof l>, diagnosticScenario: ReturnType<typeof l>, applicationScenario: ReturnType<typeof l>, counterfactual: ReturnType<typeof l>, transferScenario: ReturnType<typeof l>, transferCorrect: ReturnType<typeof l>, markers: { "es-CL": string[]; en: string[] }) => expandedSkillSchema.parse({ id, misconception, principle, boundary, diagnosticScenario, applicationScenario, counterfactual, transferScenario, transferCorrect, evaluationMarkers: markers, version: "0.2", ...review(id) });

export const expandedSkills: ExpandedSkill[] = [
  skill("competitive-advantage", l("Crecer, ser conocido o tener un buen producto no constituye por sí solo una ventaja sostenible.", "Growth, awareness or a good product does not by itself constitute sustainable advantage."), l("La ventaja existe cuando un mecanismo permite crear más valor o capturarlo con mejores economías y ese mecanismo resiste imitación o sustitución.", "Advantage exists when a mechanism creates more value or captures it with superior economics and resists imitation or substitution."), l("Toda ventaja tiene una frontera: puede erosionarse si cambia la tecnología, el canal, el poder del cliente o el costo de replicarla.", "Every advantage has a boundary: technology, channel shifts, customer power or replication cost can erode it."), l("Una plataforma crece 40%, pero sus competidores copian cada función en semanas. ¿Qué investigarías antes de llamarla ventaja competitiva?", "A platform grows 40%, but competitors copy every feature within weeks. What would you investigate before calling it competitive advantage?"), l("La empresa tiene alta retención, distribución propia y datos que reducen el costo de servir. Debes identificar cuál mecanismo explica realmente el desempeño.", "The company has high retention, proprietary distribution and data that lower cost-to-serve. Identify which mechanism actually explains performance."), l("Supón que la distribución se abre a todos los competidores y los costos de cambio caen a cero. ¿Qué parte de tu tesis sobrevive?", "Assume distribution opens to every competitor and switching costs fall to zero. Which part of your thesis survives?"), l("Una marca líder pierde exclusividad de canal, pero conserva costos estructuralmente menores. ¿Dónde permanece la ventaja?", "A leading brand loses channel exclusivity but keeps structurally lower costs. Where does the advantage remain?"), l("En el mecanismo económico que continúa creando o capturando valor y sigue siendo difícil de replicar.", "In the economic mechanism that still creates or captures value and remains difficult to replicate."), { "es-CL": ["mecanismo", "valor", "imitar", "costo", "retención"], en: ["mechanism", "value", "imit", "cost", "retention"] }),
  skill("pricing-strategy", l("El precio no es sólo una cifra ni un descuento: es la forma en que una empresa captura parte del valor que crea.", "Price is not merely a number or discount; it is an architecture for capturing part of the value created."), l("Una estrategia de precios conecta la métrica de cobro con los segmentos, la disposición a pagar, las alternativas disponibles y el costo de atender a cada cliente.", "Pricing strategy connects the charging metric, segments, willingness to pay, alternatives and cost-to-serve."), l("Capturar más valor hoy puede frenar la adopción, cambiar la composición de clientes o provocar una respuesta competitiva.", "Capturing more value today can slow adoption, alter customer mix or invite a competitive response."), l("Un producto de software tiene usuarios intensivos y ocasionales, pero cobra el mismo monto por usuario. ¿Qué evidencia necesitarías antes de subir el precio?", "A software product has intensive and occasional users but charges the same amount per seat. What evidence do you need before raising price?"), l("El segmento intensivo obtiene cinco veces más ahorro, requiere más soporte y dispone de menos alternativas. Diseña una lógica de precios, no sólo una cifra nueva.", "The intensive segment gets five times more savings, creates more support demand and has fewer alternatives. Design a pricing logic, not just a new number."), l("Supón que aumenta la disposición a pagar, pero la métrica elegida penaliza precisamente a quienes más usan el producto. ¿Qué cambiarías?", "Assume willingness to pay rises, but the chosen metric penalizes the users who adopt most. What would you change?"), l("Dos segmentos reciben un valor distinto y también tienen costos de atención diferentes. ¿Qué debería lograr una arquitectura de precios sólida?", "Two segments receive different value and cost different amounts to serve. What should a sound pricing architecture do?"), l("Alinear la métrica de cobro con el valor y el costo, sin perjudicar la adopción ni la coherencia entre segmentos.", "Align the charging metric with value and cost while preserving adoption and coherence across segments."), { "es-CL": ["valor", "segment", "métrica", "costo", "adopción"], en: ["value", "segment", "metric", "cost", "adoption"] }),
  skill("switching-costs", l("Una retención alta no demuestra por sí sola que existan costos de cambio: los clientes también pueden quedarse porque están satisfechos o simplemente porque no han evaluado alternativas.", "High retention does not prove switching costs: customers may stay because of satisfaction or inattention."), l("Los costos de cambio pueden surgir de la migración, el aprendizaje, el riesgo, las integraciones, los datos o la coordinación. Importan cuando son significativos frente al beneficio de cambiar.", "Switching costs arise from migration, learning, risk, integration, data or coordination; they matter when material relative to the benefit of switching."), l("La fricción puede proteger ingresos a corto plazo, pero destruir confianza y adopción a largo plazo si el cliente la percibe como una barrera artificial.", "Friction can protect revenue short term and destroy trust or adoption long term when perceived as artificial lock-in."), l("Una empresa muestra 96% de retención, pero nunca midió la intención de cambio ni el esfuerzo de migración. ¿Cómo distinguirías la lealtad de la fricción?", "A company shows 96% retention but never measured switching intent or migration effort. How would you separate loyalty from friction?"), l("Los clientes valoran el producto, pero exportar los datos y reconstruir las integraciones toma tres meses. Decide qué parte de la retención es sostenible y cuál es vulnerable.", "Customers value the product, but exporting data and rebuilding integrations takes three months. Decide which part of retention is durable and which is vulnerable."), l("Supón que un nuevo estándar reduce la migración a dos días. ¿Qué mecanismo de retención debería reemplazar la dependencia forzada?", "Assume a new standard reduces migration to two days. Which retention mechanism must replace lock-in?"), l("Una regulación exige la portabilidad total de los datos. ¿Qué ocurre con una ventaja basada principalmente en una migración costosa?", "A regulation requires full data portability. What happens to an advantage based mainly on expensive migration?"), l("La ventaja se debilita y debe reemplazarse por valor continuo, integraciones útiles o aprendizaje que el cliente quiera conservar.", "It erodes and must be replaced by continuous value, useful integration or learning the customer wants to preserve."), { "es-CL": ["migración", "integración", "datos", "fricción", "retención"], en: ["migration", "integration", "data", "friction", "retention"] }),
  skill("financial-statements", l("Leer cada estado financiero por separado oculta que utilidad, activos y caja describen el mismo sistema desde ángulos distintos.", "Reading each financial statement separately hides that profit, assets and cash describe the same system from different angles."), l("El estado de resultados mide desempeño, el balance acumula recursos y obligaciones, y el flujo explica por qué la caja cambió.", "The income statement measures performance, the balance sheet accumulates resources and obligations, and cash flow explains why cash changed."), l("Una cifra contable puede mejorar mientras empeora la liquidez si cobranza, inventario o inversión absorben caja.", "An accounting figure can improve while liquidity worsens when receivables, inventory or investment absorb cash."), l("Las ventas crecen 30% y la utilidad sube, pero la caja cae. ¿Qué conexiones revisarías primero?", "Sales grow 30% and profit rises, but cash falls. Which connections would you inspect first?"), l("Cuentas por cobrar se duplican, inventario aumenta y la empresa capitaliza parte del desarrollo. Reconstruye la historia económica entre los tres estados.", "Receivables double, inventory rises and the company capitalizes part of development. Reconstruct the economic story across the three statements."), l("Supón que los clientes comienzan a pagar por adelantado. ¿Qué cambia primero en caja, pasivos e ingresos?", "Assume customers begin paying in advance. What changes first in cash, liabilities and revenue?"), l("Una empresa rentable consume caja por crecimiento de capital de trabajo. ¿Cuál es la lectura correcta?", "A profitable company consumes cash because working capital grows. What is the correct reading?"), l("La utilidad puede ser real y aun así requerir financiamiento porque el momento de cobro y la inversión preceden a la caja.", "Profit can be real and still require financing because collection timing and investment precede cash."), { "es-CL": ["caja", "cuentas por cobrar", "inventario", "balance", "utilidad"], en: ["cash", "receivable", "inventory", "balance", "profit"] }),
  skill("economics.unit-economics", l("Un margen promedio puede ocultar clientes, pedidos o segmentos que destruyen valor con cada unidad adicional.", "An average margin can hide customers, orders or segments that destroy value with every additional unit."), l("La unidad correcta conecta el ingreso incremental, el costo variable, la retención y la frecuencia con el comportamiento que realmente crece.", "The right unit connects incremental revenue, variable cost, retention and frequency to the behavior that actually scales."), l("Una unidad rentable no garantiza un negocio rentable si la adquisición, la capacidad fija o la concentración del uso cambian con el crecimiento.", "An attractive unit does not guarantee an attractive business if acquisition, fixed capacity or usage concentration changes with growth."), l("Una plataforma de intermediación crece rápido y reporta margen positivo por pedido, pero necesita subsidios recurrentes para retener compradores. ¿Cuál es la unidad económica real?", "A marketplace grows quickly and reports positive margin per order but needs recurring subsidies to retain buyers. What is the real economic unit?"), l("Los clientes nuevos generan pérdidas durante tres meses y luego mejoran, salvo un segmento intensivo que requiere mucho soporte. Define las cohortes y el horizonte antes de calcular promedios.", "New customers lose money for three months and then improve, except for an intensive high-support segment. Define cohorts and horizon before averaging."), l("Supón que la frecuencia de uso se duplica y el costo variable también. ¿Qué métrica te indicaría si el crecimiento crea valor?", "Assume usage frequency doubles and variable cost doubles with it. Which metric tells you whether growth creates value?"), l("Los ingresos por usuario aumentan, pero el costo de atenderlo crece aún más rápido. ¿Qué concluyes?", "Revenue grows per user, but cost-to-serve grows faster. What do you conclude?"), l("La economía unitaria se deteriora; el crecimiento amplifica el problema, salvo que cambien el precio, el costo o el comportamiento.", "Unit economics deteriorate; growth amplifies the problem unless price, cost or behavior changes."), { "es-CL": ["unidad", "ingreso", "costo variable", "cohorte", "margen"], en: ["unit", "revenue", "variable cost", "cohort", "margin"] }),
  skill("contribution-margin", l("El margen bruto y el margen de contribución responden preguntas distintas y no clasifican todos los costos de la misma manera.", "Gross margin and contribution margin do not answer the same question or classify every cost the same way."), l("El margen de contribución muestra cuánto aporta cada unidad después de descontar los costos que varían al atenderla. Ese monto queda disponible para cubrir la estructura fija y generar utilidad.", "Contribution margin shows what a unit leaves after costs that change with serving it, available to cover structure and profit."), l("La clasificación depende del horizonte y del factor que origina el costo: algo que hoy parece fijo puede volverse variable cuando se supera la capacidad disponible.", "Classification depends on horizon and driver: a cost may look fixed today and become variable when capacity is crossed."), l("Un servicio reporta 70% de margen bruto, pero cada cliente nuevo exige incorporación y soporte externo. ¿Qué margen usarías para decidir si conviene crecer?", "A service reports 70% gross margin, but every new customer requires onboarding and external support. Which margin would you use to decide growth?"), l("El precio es US$100 por cliente; la infraestructura cuesta US$15, el soporte US$20 y las comisiones US$10. La estructura central cuesta US$500 mil.", "Price is US$100; infrastructure costs US$15, support US$20 and commissions US$10 per customer. Central overhead costs US$500k."), l("Supón que el equipo de soporte alcanza su límite y debes agregar capacidad por bloques. ¿Cómo cambia el análisis marginal?", "Assume support reaches capacity and must be added in blocks. How does the marginal reading change?"), l("Un producto tiene margen bruto positivo, pero margen de contribución negativo por cliente. ¿Qué ocurriría si creciera sin rediseñar su operación?", "A product has positive gross margin but negative contribution per customer. What does growth without redesign imply?"), l("Cada cliente adicional aumenta la pérdida antes de cubrir los costos fijos; crecer empeora el resultado.", "Every additional customer increases loss before covering overhead; growth worsens the result."), { "es-CL": ["contribución", "variable", "precio", "soporte", "capacidad"], en: ["contribution", "variable", "price", "support", "capacity"] }),
  skill("elasticity", l("La elasticidad no es una propiedad fija del producto: cambia según el segmento, el horizonte de tiempo, las alternativas y la forma en que se presenta el precio.", "Elasticity is not a fixed property of a product: it changes by segment, horizon, alternatives and framing."), l("La elasticidad mide cuánto cambia proporcionalmente la demanda frente a una variación proporcional del precio, dentro de una unidad y un período bien definidos.", "Elasticity measures the proportional demand response to a proportional price change with a clear unit and time period."), l("Una prueba aislada puede confundir anticipación, selección o estacionalidad con una respuesta causada por el precio.", "A local test can confuse anticipation, selection or seasonality with a causal response to price."), l("Un servicio aumenta su precio en 10% y pierde 4% de volumen durante el primer mes. ¿Qué información falta antes de afirmar que la demanda es inelástica?", "A service raises price 10% and loses 4% of volume in one month. What is missing before declaring demand inelastic?"), l("Las grandes empresas casi no cambian su comportamiento, mientras las pymes migran a una alternativa gratuita después de tres meses. Interpreta la elasticidad por segmento y horizonte.", "The enterprise segment barely changes while small businesses migrate to a free alternative after three months. Interpret elasticity by segment and horizon."), l("Supón que un competidor elimina su plan gratuito. ¿Cómo cambiaría la elasticidad que esperas observar?", "Assume a competitor removes its free tier. How does that affect the elasticity you expect to observe?"), l("El mismo aumento de precio genera respuestas distintas entre segmentos que tienen alternativas diferentes. ¿Por qué?", "The same price increase creates different responses in segments with different alternatives. Why?"), l("Porque la elasticidad depende de las alternativas disponibles, el valor percibido y el tiempo de reacción, no sólo del porcentaje de aumento.", "Because elasticity depends on substitution context, value and time, not only the price percentage."), { "es-CL": ["precio", "demanda", "segmento", "alternativa", "horizonte"], en: ["price", "demand", "segment", "alternative", "horizon"] }),
  skill("marginal-cost", l("Dividir los costos totales por el número de unidades entrega un costo promedio, no necesariamente el costo de producir o atender una unidad adicional.", "Dividing total costs by units gives average cost, not necessarily the cost of one additional unit."), l("El costo marginal identifica qué recursos adicionales exige una unidad más y cambia cuando se superan los límites de capacidad.", "Marginal cost identifies additional resources activated by one more unit and changes when capacity thresholds are crossed."), l("Un costo cercano a cero dentro de la capacidad disponible no seguirá siendo cero para siempre: el soporte, la infraestructura o el riesgo pueden crecer por tramos.", "Near zero within capacity does not mean zero forever: support, infrastructure or risk can appear in steps."), l("Una plataforma afirma que cada usuario nuevo cuesta cero porque sus servidores ya están pagados. ¿Qué factores revisarías?", "A platform claims each new user costs zero because its servers are already paid. Which drivers would you inspect?"), l("Los usuarios de baja intensidad caben dentro de la capacidad actual, pero los intensivos exigen procesamiento, moderación y soporte adicionales. Calcula el costo según el comportamiento, no sólo por cuenta.", "Light users fit within capacity, but intensive users activate processing, moderation and support. Calculate by behavior, not just account."), l("Supón que el siguiente bloque de infraestructura cuesta US$200 mil y se activa al sumar un solo cliente. ¿Qué horizonte deberías considerar?", "Assume the next infrastructure block costs US$200k and is triggered by one more customer. What is the relevant horizon?"), l("El costo promedio disminuye, pero un cliente nuevo obliga a habilitar un turno completo. ¿Qué costo debería definir si aceptas ese cliente?", "Average cost falls, but one new customer triggers an entire additional shift. Which cost drives acceptance?"), l("El costo incremental del turno y de los recursos asociados, no el promedio histórico.", "The incremental shift cost and associated resources, not the historical average."), { "es-CL": ["incremental", "capacidad", "unidad", "variable", "escalón"], en: ["incremental", "capacity", "unit", "variable", "step"] }),
  skill("segmentation", l("Segmentar por industria o tamaño sólo es útil si esas categorías explican diferencias relevantes en las necesidades o el comportamiento.", "Segmenting by industry or size is useful only when those categories explain relevant differences in need or behavior."), l("Un segmento útil agrupa clientes con necesidades, disposición a pagar, costos o canales similares y responde de manera distinta frente a una decisión.", "An actionable segment groups customers with similar needs, willingness to pay, costs or channels and responds differently to a decision."), l("Demasiados segmentos eliminan economías de escala; muy pocos esconden diferencias que deberían cambiar el producto o su rentabilidad.", "Too many segments destroy scale and too few hide differences that change product or economics."), l("Una empresa divide a sus clientes entre pymes y grandes empresas, pero dentro de cada grupo observa comportamientos opuestos. ¿Cómo volverías a segmentarlos?", "A company divides customers into SMB and enterprise, but both groups show opposite behaviors within each category. How would you resegment?"), l("Algunos clientes priorizan la velocidad, otros el control y otros la integración. Cada necesidad cambia la adopción, el precio y el soporte requerido.", "Some customers prioritize speed, others control and others integration. Each need changes adoption, price and support."), l("Supón que dos segmentos buscan el mismo resultado, pero llegan por canales con costos radicalmente distintos. ¿Los mantendrías juntos?", "Assume two segments need the same outcome but arrive through channels with radically different costs. Do you keep them together?"), l("Dos clientes del mismo tamaño responden de manera distinta porque uno valora el control y el otro la velocidad. ¿Qué variable permitiría segmentarlos mejor?", "Two customers of the same size respond differently because one values control and the other speed. Which variable segments better?"), l("La necesidad o el comportamiento que cambia la decisión de producto, precio o canal.", "The need or behavior that changes the product, pricing or channel decision."), { "es-CL": ["necesidad", "comportamiento", "segmento", "precio", "canal"], en: ["need", "behavior", "segment", "price", "channel"] }),
  skill("customer-acquisition", l("Un costo de adquisición bajo no implica un crecimiento sano si la atribución, la calidad de las cohortes o la saturación del canal están mal medidas.", "Low CAC does not imply healthy growth when attribution, cohort quality or channel saturation are mismeasured."), l("La adquisición conecta el costo incremental, el efecto real de cada canal, la conversión, la retención y el valor de la cohorte adquirida.", "Acquisition connects incremental cost, channel causality, conversion, retention and the value of the acquired cohort."), l("Al aumentar la inversión cambian las subastas, la audiencia y la composición de clientes; el costo marginal de adquisición puede deteriorarse aunque el promedio histórico se mantenga estable.", "Scaling changes auctions, audience and mix; marginal CAC can deteriorate while the historical average looks stable."), l("Marketing reporta un costo de adquisición de US$80 mediante atribución de último clic. ¿Qué verificarías antes de duplicar el presupuesto?", "Marketing reports US$80 CAC using last-click attribution. What would you verify before doubling budget?"), l("El canal pagado captura demanda que ya buscaba la marca y las cohortes nuevas retienen menos. Separa el efecto incremental, el costo marginal de adquisición y el valor de cada cohorte.", "The paid channel captures branded demand and newer cohorts retain less. Separate incrementality, marginal CAC and cohort value."), l("Supón que el presupuesto adicional aumenta el costo de adquisición en 45% y reduce la calidad de las cohortes. ¿Qué señal debería detener la inversión?", "Assume additional budget raises CAC 45% and lowers cohort quality. Which signal stops investment?"), l("Un canal muestra un costo promedio estable, pero los clientes más recientes retienen la mitad. ¿Qué métrica debería pesar más?", "A channel shows stable average CAC, but recent customers retain at half the rate. Which metric matters?"), l("El valor incremental de las nuevas cohortes frente al costo marginal de adquirirlas, no el promedio acumulado.", "The incremental value of new cohorts relative to marginal CAC, not the accumulated average."), { "es-CL": ["adquisición", "cohorte", "retención", "incremental", "canal"], en: ["CAC", "cohort", "retention", "incremental", "channel"] }),
  skill("process-design", l("Documentar una secuencia de pasos no basta: un proceso es un sistema de entradas, decisiones, traspasos, variabilidad y resultados.", "Documenting steps is not enough: a process is a system of inputs, decisions, handoffs, variability and outcomes."), l("Diseñar un proceso exige hacer visible el flujo, ubicar las decisiones y reducir las esperas, el retrabajo y los traspasos innecesarios.", "Process design makes flow visible, locates decisions and reduces waiting, rework and unnecessary transfer."), l("Optimizar cada actividad por separado puede aumentar el tiempo total si genera lotes, inventario o más coordinación.", "Optimizing every local activity can worsen total time when it increases batches, inventory or coordination."), l("La incorporación de un cliente tarda 18 días, aunque cada equipo completa su parte en menos de cuatro horas. ¿Dónde buscarías el problema primero?", "An onboarding takes 18 days even though every team completes its part in under four hours. Where would you look first?"), l("El trabajo pasa por cinco equipos, espera varias aprobaciones y retrocede dos veces por datos incompletos. Rediseña el flujo de principio a fin.", "Work passes through five teams, waits for approvals and returns twice for incomplete data. Redesign the end-to-end flow."), l("Supón que automatizas la tarea más lenta, pero las aprobaciones siguen acumulándose para una revisión semanal. ¿Qué cambia realmente?", "Assume you automate the slowest task but approvals still accumulate in weekly batches. What actually changes?"), l("Cada actividad se acelera, pero el tiempo total no disminuye porque dominan las esperas entre equipos. ¿Qué debe rediseñarse?", "Every activity speeds up, but total time does not fall because waiting between teams dominates. What must be redesigned?"), l("El flujo, los traspasos y las reglas de decisión; no sólo la velocidad de cada tarea.", "The flow, handoffs and decision rules, not only the speed of each task."), { "es-CL": ["flujo", "espera", "traspaso", "retrabajo", "decisión"], en: ["flow", "wait", "handoff", "rework", "decision"] }),
  skill("bottlenecks", l("El recurso más ocupado o más visible no siempre es la restricción que limita el rendimiento total del sistema.", "The busiest or most visible resource is not always the constraint governing system throughput."), l("La restricción es el punto cuya capacidad efectiva limita la producción total. Mejorar otras etapas sólo genera más espera o inventario.", "The constraint is the point whose effective capacity limits total output; improving elsewhere only creates waiting or inventory."), l("Después de una mejora, la restricción puede trasladarse. Además, puede ser una regla, una falta de información o una decisión, no sólo una máquina.", "The constraint can move after improvement and may be a rule, information or decision, not only a machine."), l("Un equipo contrata más vendedores, pero las activaciones mensuales no aumentan. ¿Cómo identificarías la restricción real?", "A team hires more salespeople, but monthly activations do not change. How would you identify the real constraint?"), l("Ventas genera 200 contratos, Implementación procesa 120 y Legal aprueba 90. Decide dónde intervenir y qué no conviene acelerar todavía.", "Sales generates 200 contracts, implementation processes 120 and legal approves 90. Decide where to intervene and what not to accelerate yet."), l("Supón que Legal duplica su capacidad y ahora Implementación acumula trabajo pendiente. ¿Cómo cambia la prioridad?", "Assume legal doubles capacity and implementation now accumulates a queue. How does priority change?"), l("Marketing duplica la demanda, pero Producción no aumenta las entregas. ¿Qué efecto tiene la campaña?", "Marketing doubles demand, but production does not increase deliveries. What effect does the campaign have?"), l("Aumenta el trabajo pendiente o las promesas incumplidas; la producción total no crecerá mientras se mantenga la restricción.", "It increases backlog or broken promises; throughput does not rise while the constraint remains."), { "es-CL": ["restricción", "capacidad", "rendimiento", "cola", "flujo"], en: ["constraint", "capacity", "throughput", "queue", "flow"] }),
  skill("decision-rights", l("Centralizar todas las decisiones puede dar una sensación de control, pero también elimina contexto, reduce velocidad y diluye la responsabilidad por los resultados.", "Centralizing every decision improves apparent control but can destroy context, speed and accountability."), l("La autoridad debe ubicarse donde coincidan información suficiente, consecuencias visibles y responsabilidad por el resultado.", "Decision rights should place authority where sufficient information, visible consequences and outcome accountability coexist."), l("Descentralizar sin límites, métricas ni mecanismos de escalamiento convierte la autonomía en inconsistencia o en riesgo invisible.", "Decentralizing without boundaries, metrics or escalation turns autonomy into inconsistency or invisible risk."), l("Una empresa exige la aprobación del CEO para descuentos pequeños y pierde negocios cada semana. ¿A quién trasladarías esa decisión y qué límites establecerías?", "A company requires CEO approval for small discounts and loses deals every week. Which decision would you move and with what guardrails?"), l("Ventas conoce al cliente, Finanzas conoce el margen y Producto conoce la capacidad disponible. Define quién decide, qué información debe consultar y cuándo debe escalar.", "Sales knows the customer, Finance knows margin and Product knows capacity. Design authority, required input and escalation."), l("Supón que las decisiones locales aceleran las ventas, pero deterioran el margen de forma acumulativa. ¿Qué mecanismo falta?", "Assume local decisions accelerate sales but cumulatively erode margin. Which mechanism is missing?"), l("Un equipo dispone de toda la información local, pero no asume el costo de sus decisiones. ¿Debería tener autoridad completa?", "A team has all local information but does not bear the cost of its decisions. Should it have full authority?"), l("No, salvo que existan responsabilidad por resultados, límites y mecanismos de escalamiento que conecten la decisión local con el desempeño del sistema.", "Not without accountability, boundaries and escalation connecting local decisions to system outcomes."), { "es-CL": ["autoridad", "contexto", "responsabilidad", "límite", "escalamiento"], en: ["authority", "context", "accountability", "boundary", "escalation"] }),
  skill("organizational-design", l("El organigrama no es todo el diseño: la estructura, las formas de coordinación, los incentivos y la información deben apoyar el trabajo estratégico.", "An org chart is not the design: structure, interfaces, incentives and information must support strategic work."), l("El diseño organizacional agrupa tareas interdependientes, define cómo coordinarlas y distribuye las decisiones según el sistema de actividades que exige la estrategia.", "Organizational design groups interdependencies, defines coordination and distributes decisions according to the required activity system."), l("Cada forma de agrupar equipos facilita algunas coordinaciones y crea nuevas fronteras; ninguna estructura elimina por completo los costos de coordinación.", "Every grouping optimizes some coordination and creates other boundaries; no structure is free of interface costs."), l("Una empresa se organiza por funciones, pero cada lanzamiento exige meses de coordinación transversal. ¿Qué rediseñarías antes de cambiar el organigrama?", "A company is organized by function, but every launch requires months of cross-functional coordination. What would you redesign before moving boxes?"), l("Producto, Operaciones y Ventas comparten resultados, pero reciben métricas e información en ciclos distintos. Diseña sus mecanismos de coordinación y derechos de decisión.", "Product, Operations and Sales share outcomes, but metrics and information arrive on different cycles. Design interfaces and rights."), l("Supón que creas equipos autónomos y cada uno duplica capacidades críticas. ¿Qué debería permanecer compartido?", "Assume you create autonomous squads and they duplicate critical capabilities in every unit. What should remain shared?"), l("Dos equipos dependen diariamente uno del otro, pero pertenecen a áreas con objetivos opuestos. ¿Qué indica eso?", "Two teams depend on each other daily but report into areas with opposing goals. What does that indicate?"), l("Que los mecanismos de coordinación y los incentivos no reflejan la interdependencia real del trabajo.", "The interface and incentives do not reflect the work's real interdependence."), { "es-CL": ["interdependencia", "interfaz", "estructura", "incentivo", "coordinación"], en: ["interdependence", "interface", "structure", "incentive", "coordination"] }),
  skill("probability", l("Expresar la incertidumbre sólo como algo «posible» o «seguro» impide comparar decisiones y actualizar lo que creemos.", "Expressing uncertainty as ‘possible’ or ‘certain’ prevents decision comparison and belief updating."), l("La probabilidad permite ajustar una estimación a la evidencia y combinar la posibilidad de que algo ocurra, su impacto y la nueva información disponible.", "Probability calibrates a belief against evidence and lets us combine likelihood, impact and new information."), l("Una cifra precisa no garantiza una buena estimación. También importan el rango, la frecuencia histórica y la forma en que nueva evidencia modificaría el cálculo.", "A precise number does not guarantee a good estimate; ranges, base rates and evidence updates matter."), l("Un equipo dice que un lanzamiento «probablemente funcionará», pero no define qué significa tener éxito ni utiliza una referencia histórica. ¿Cómo convertirías esa afirmación en algo evaluable?", "A team says a launch will ‘probably work’ without defining success or historical reference. How would you make that claim evaluable?"), l("De veinte lanzamientos comparables, seis superaron la meta. El nuevo tiene un canal mejor, pero una retención inicial más baja. Formula una estimación calibrada.", "Six of twenty comparable launches beat target. The new one has a better channel but lower early retention. Form a calibrated estimate."), l("Supón que aparece una señal temprana muy positiva, pero históricamente esa señal produce muchos falsos positivos. ¿Cuánto debería cambiar tu estimación?", "Assume a very positive early signal appears, but historically it has many false positives. How much do you update?"), l("Una predicción con 70% de probabilidad falla una vez. ¿Demuestra eso que estaba mal calibrada?", "A 70% forecast fails once. Does that prove it was miscalibrated?"), l("No. La calibración se evalúa sobre muchas predicciones comparables, no a partir de un resultado aislado.", "No; calibration is evaluated across many comparable forecasts, not one outcome."), { "es-CL": ["probabilidad", "evidencia", "base", "rango", "calibr"], en: ["probability", "evidence", "base", "range", "calibr"] }),
  skill("experimentation", l("Comparar el antes y el después rara vez permite aislar la causalidad: la estacionalidad, la selección y otros cambios pueden contaminar el resultado.", "Before-and-after comparison rarely isolates causality: seasonality, selection and other changes contaminate the result."), l("Un experimento útil define la unidad de análisis, la intervención, el contrafactual, la métrica y el período de medición antes de observar los resultados.", "A useful experiment defines unit, intervention, counterfactual, metric and window before observing results."), l("La significancia estadística no compensa una mala métrica ni una intervención que modifica varias cosas al mismo tiempo.", "Statistical significance does not rescue a poor metric or a treatment that changes multiple things at once."), l("Un nuevo proceso de incorporación mejora la activación en 12% frente al mes anterior. ¿Qué diseño permitiría atribuir ese cambio a la intervención?", "A new onboarding improves activation 12% versus the previous month. Which design would let you attribute the change?"), l("El equipo puede asignar aleatoriamente las cuentas, pero los usuarios comparten información dentro de cada empresa. Define la unidad de análisis y el riesgo de contaminación.", "The team can randomize by account, but users share information within each company. Define the unit and contamination risk."), l("Supón que la prueba mejora la activación, pero empeora la retención a 60 días. ¿Qué resultado debería decidir?", "Assume the test improves activation but worsens 60-day retention. Which outcome decides?"), l("El grupo intervenido convierte más, pero también recibió una campaña distinta. ¿Qué se perdió?", "The treatment group converts more but also received a different campaign. What was lost?"), l("Se perdió un contrafactual limpio: ya no es posible atribuir el efecto a una sola intervención.", "A clean counterfactual: the effect can no longer be attributed to one intervention."), { "es-CL": ["contrafactual", "aleatori", "métrica", "unidad", "causal"], en: ["counterfactual", "random", "metric", "unit", "causal"] }),
  skill("ai.model-landscape", l("Elegir un modelo por una prueba comparativa general confunde la capacidad del modelo con el desempeño del sistema completo.", "Choosing a model from a general benchmark confuses base capability with full-system performance."), l("El resultado depende del modelo, el contexto, las herramientas, los datos, las evaluaciones y el flujo de trabajo. El modelo es sólo una capa del producto.", "Outcomes depend on model, context, tools, data, evaluations and workflow; the model is one product layer."), l("El modelo con mejor desempeño promedio puede perder frente a un sistema más controlable, económico o especializado en la tarea real.", "The best average capability can lose to a system that is more controllable, cheaper or specialized for the real task."), l("Dos modelos lideran pruebas distintas, pero uno falla dentro del flujo de trabajo real. ¿Cómo decidirías sin confundir la prueba del modelo con la calidad del producto?", "Two models lead different benchmarks, but one fails in the real workflow. How would you decide without turning the benchmark into the product?"), l("La tarea exige datos privados, herramientas internas y una latencia inferior a dos segundos. Diseña una evaluación del sistema completo.", "The task requires private data, internal tools and latency under two seconds. Design a system evaluation."), l("Supón que el modelo líder cambia cada tres meses. ¿Qué arquitectura permitiría sustituirlo sin rehacer el producto?", "Assume the leading model changes every three months. Which architecture preserves substitutability?"), l("Un modelo más pequeño supera al líder dentro de un flujo que recupera información y valida los resultados. ¿Qué demuestra?", "A smaller model beats the leader inside a workflow with retrieval and validation. What does that demonstrate?"), l("Que la capacidad del producto surge del sistema completo, no del modelo aislado.", "That product capability emerges from the full system, not the model in isolation."), { "es-CL": ["modelo", "flujo", "evaluación", "herramienta", "sistema"], en: ["model", "workflow", "evaluation", "tool", "system"] }),
  skill("ai-training-inference", l("El entrenamiento y la inferencia no son dos nombres para el mismo costo ni ocurren en el mismo momento del negocio.", "Training and inference are not two names for the same cost and do not occur at the same economic moment."), l("El entrenamiento crea o adapta una capacidad; la inferencia la utiliza cada vez que el producto responde y, por eso, se relaciona directamente con el costo variable.", "Training creates or adapts capability; inference consumes it on each use and directly connects product behavior to variable cost."), l("Optimizar el entrenamiento no garantiza una operación económica: el contexto, la frecuencia de uso, el modelo y la latencia determinan el costo de inferencia.", "Optimizing training does not guarantee serving economics; context, frequency, model and latency govern inference."), l("Un equipo presupuestó el ajuste del modelo, pero los costos se disparan después del lanzamiento. ¿Qué parte del sistema probablemente ignoró?", "A team budgeted fine-tuning, but cost explodes after launch. Which part of the system did it probably ignore?"), l("Cada usuario realiza veinte solicitudes diarias con un contexto extenso. Separa la inversión inicial del costo recurrente.", "Each user runs twenty daily requests with long context. Separate initial investment from recurring cost."), l("Supón que entrenar el modelo se vuelve gratuito, pero el uso se multiplica por diez. ¿Qué costos permanecen?", "Assume training becomes free, but usage grows tenfold. Which economics remain?"), l("El modelo puede ser costoso de crear y barato de usar, o al revés. ¿Qué distinción debería orientar el modelo de precios?", "The model costs a lot to create and little to use, or vice versa. Which distinction guides pricing?"), l("Debes separar el costo de desarrollar la capacidad del costo marginal de utilizarla.", "Separate the cost of developing capability from the marginal cost of running it."), { "es-CL": ["entrenamiento", "inferencia", "uso", "recurrente", "costo"], en: ["training", "inference", "usage", "recurring", "cost"] }),
  skill("ai-tokens-context", l("Dar más contexto al modelo no garantiza mayor memoria, comprensión o precisión.", "More context does not automatically mean more memory, understanding or accuracy."), l("Los tokens forman el presupuesto de entrada y salida. El contexto útil compite con el ruido, el costo, la latencia y la capacidad efectiva de atención.", "Tokens are an input-output budget; useful context competes with noise, cost, latency and effective attention."), l("Agregar documentos puede empeorar los resultados si el sistema no recupera, prioriza y actualiza bien la información relevante.", "Adding documents can worsen outcomes when retrieval, priority or freshness fail to distinguish relevant signal."), l("Un asistente recibe todo el historial del cliente y responde peor mientras más antigua es la cuenta. ¿Qué investigarías?", "An assistant receives the customer's entire history and performs worse for older accounts. What would you investigate?"), l("La instrucción incluye 80 páginas, pero sólo tres párrafos podrían cambiar la decisión. Diseña cómo seleccionar, resumir y rastrear la información.", "The prompt includes 80 pages, but only three paragraphs change the decision. Design selection, summarization and traceability."), l("Supón que duplicas el contexto disponible sin cambiar el modelo. ¿Qué riesgo también aumenta?", "Assume available context doubles without changing the model. Which risk also grows?"), l("Un modelo con una ventana más amplia recibe más información, pero pierde precisión. ¿Cómo es posible?", "A model with a larger window receives more information and accuracy falls. Why is that possible?"), l("Porque la información irrelevante compite con la señal útil, aumenta el costo y puede confundir la tarea.", "Because irrelevant context competes with signal, raises cost and can confuse the task."), { "es-CL": ["contexto", "token", "ruido", "información", "latencia"], en: ["context", "token", "noise", "retrieval", "latency"] }),
  skill("ai-evaluation-basics", l("Una demostración convincente no basta para afirmar que el sistema tendrá una calidad estable en producción.", "A compelling demo is not sufficient evidence of stable production quality."), l("Una evaluación sólida requiere tareas representativas, criterios observables, casos límite y una referencia conectada con el resultado real del flujo de trabajo.", "Evaluation requires representative tasks, observable criteria, edge cases and a baseline connected to workflow outcomes."), l("Un puntaje promedio puede ocultar fallas graves en segmentos poco frecuentes, costosos o regulados.", "An average score can hide severe failures in rare, expensive or regulated segments."), l("Un copiloto impresiona en diez ejemplos elegidos por el equipo. ¿Qué necesitas comprobar antes de lanzarlo?", "A copilot impresses on ten examples selected by the team. What do you need before launching it?"), l("La tarea abarca distintos idiomas, tipos de clientes y niveles de riesgo. Construye un conjunto representativo y define umbrales para cada segmento.", "The task spans languages, customers and risk levels. Build a representative set with segment-level thresholds."), l("Supón que mejora el promedio, pero se duplican las fallas de alto impacto. ¿Qué resultado debería pesar más?", "Assume the average improves but high-impact failures double. Which evaluation matters?"), l("Un modelo mejora cinco puntos en promedio, pero falla más en el segmento regulado. ¿Es realmente mejor?", "A model gains five average points and fails more in the regulated segment. Is it better?"), l("No necesariamente. Debe superar los umbrales relevantes de cada segmento, considerando el costo de los errores.", "Not necessarily; it must clear relevant thresholds by segment and error cost."), { "es-CL": ["evaluación", "umbral", "segmento", "falla", "representativ"], en: ["evaluation", "threshold", "segment", "failure", "representative"] }),
  skill("ai-inference-economics", l("Tratar la IA como si fuera software con costo marginal cero oculta que un mayor uso puede reducir el margen.", "Treating AI as zero-marginal-cost software hides that more engagement can reduce margin."), l("La economía de inferencia relaciona la frecuencia de uso, los tokens, el modelo, la latencia y la arquitectura con el costo de obtener un resultado útil.", "Inference economics connects frequency, tokens, model, latency and architecture to cost per useful outcome."), l("Reducir el costo de cada llamada puede empeorar el resultado económico si disminuye la calidad y aumentan los reintentos, el soporte o el abandono.", "Lowering cost per call can worsen economics if quality drops and triggers retries, support or churn."), l("Una aplicación duplica su uso y sus ingresos crecen 25%, pero el margen disminuye. ¿Qué variables separarías primero?", "An app doubles usage and revenue grows 25%, but margin falls. Which decomposition would you perform first?"), l("Los usuarios intensivos generan cuatro veces más tokens, pero sólo 30% más ingresos. Modela el costo por segmento y por resultado.", "Intensive users generate four times more tokens and only 30% more revenue. Model cost by segment and outcome."), l("Supón que un modelo más barato necesita dos intentos adicionales para alcanzar la calidad requerida. ¿Sigue siendo más económico?", "Assume a cheaper model needs two additional attempts to reach quality. Is it still more economical?"), l("El costo por token disminuye, pero los reintentos duplican el costo de cada tarea resuelta. ¿Qué métrica importa?", "Cost per token falls, but retries double cost per resolved task. Which metric matters?"), l("El costo por resultado útil que supera el umbral de calidad, no el costo nominal de cada llamada.", "Cost per useful outcome that clears the quality threshold, not nominal cost per call."), { "es-CL": ["inferencia", "token", "uso", "margen", "resultado"], en: ["inference", "token", "usage", "margin", "outcome"] }),
  skill("ai-cost-quality", l("Elegir siempre el modelo más capaz ignora que una mejora adicional de calidad puede no cambiar el resultado del negocio.", "Always choosing the most capable model ignores that additional quality may not change the business outcome."), l("La frontera entre costo y calidad busca el sistema más económico que supere de manera confiable el umbral requerido para cada tarea.", "The cost-quality frontier seeks the lowest-cost system that reliably clears the task's required threshold."), l("El umbral cambia según el riesgo, el segmento y la capacidad de verificación; una sola configuración rara vez sirve para todas las tareas.", "The threshold changes by risk, segment and verification ability; one configuration rarely fits every task."), l("Un modelo avanzado mejora la precisión de 91% a 94%, pero cuesta cinco veces más. ¿Qué determinaría si vale la pena?", "A premium model improves accuracy from 91% to 94% and costs five times more. What determines whether it is worth it?"), l("Las consultas simples permiten una revisión automática; las decisiones regulatorias exigen verificación humana. Diseña una regla para asignar cada tarea según su umbral.", "Simple queries allow automated review; regulatory decisions require human verification. Design threshold-based routing."), l("Supón que el error restante tiene un impacto cien veces mayor en un segmento pequeño. ¿Cómo cambia el equilibrio entre costo y calidad?", "Assume the remaining error has one hundred times more impact in a small segment. How does the frontier change?"), l("El modelo más costoso mejora una métrica, pero no cambia las decisiones del usuario. ¿Qué concluyes?", "The most expensive model improves a metric without changing user decisions. What do you conclude?"), l("La calidad adicional no crea suficiente valor; conviene usar el sistema más económico que supere el umbral relevante.", "The added quality does not create enough value; use the cheapest system that clears the relevant threshold."), { "es-CL": ["calidad", "umbral", "costo", "riesgo", "asignar"], en: ["quality", "threshold", "cost", "risk", "routing"] }),
  skill("ai-gross-margins", l("Un margen bruto promedio puede ocultar que los clientes más atractivos para Ventas son los menos rentables para el negocio.", "Average gross margin can hide that the best commercial customers are the worst economic customers."), l("El margen de un producto de IA combina ingresos, inferencia, soporte, supervisión técnica y concentración del uso por cohorte o segmento.", "AI margin combines revenue, inference, support, observability and usage concentration by cohort or segment."), l("El margen inicial puede mejorar al optimizar el sistema y asignar mejor los modelos, pero también puede deteriorarse si el uso crece más rápido que el precio.", "Initial margin can improve with optimization and routing, but also deteriorate when usage grows faster than price."), l("Un producto reporta 68% de margen, pero el 10% de usuarios más intensivos tiene margen negativo. ¿Cómo evaluarías el crecimiento?", "A product reports 68% margin, but the top usage decile has negative margin. How would you evaluate growth?"), l("Los clientes grandes pagan más, pero utilizan contextos extensos y soporte dedicado. Separa el margen por cohorte y por los factores que generan el costo.", "Enterprise customers pay more but use long context and dedicated support. Separate margin by cohort and driver."), l("Supón que aumenta la adopción dentro de las cuentas, pero no el precio contratado. ¿Qué medidas podrían proteger el margen?", "Assume adoption grows within accounts without increasing contract price. Which levers protect margin?"), l("El margen promedio mejora mientras los nuevos clientes de uso intensivo generan pérdidas. ¿Qué señal utilizarías?", "Average margin improves while new intensive customers lose money. Which signal would you use?"), l("El margen por cohorte y comportamiento de uso, porque anticipa la rentabilidad del crecimiento futuro.", "Margin by cohort and usage behavior because it anticipates the economics of future growth."), { "es-CL": ["margen", "cohorte", "uso", "soporte", "precio"], en: ["margin", "cohort", "usage", "support", "price"] }),
  skill("ai-pricing", l("Copiar el cobro por usuario típico del software como servicio puede desconectar los ingresos tanto del valor creado como del costo variable de la IA.", "Copying per-seat SaaS pricing can misalign revenue with AI value and variable cost."), l("El modelo de precios debe conectar la unidad de valor, el comportamiento de uso y la variación de los costos con una forma de cobro que el cliente pueda comprender.", "AI pricing must connect the unit of value, usage behavior, cost volatility and a customer-comprehensible experience."), l("Cobrar exactamente según el costo protege el margen, pero puede trasladar la incertidumbre al cliente y frenar la adopción.", "Charging exactly by cost protects margin but can transfer uncertainty to customers and slow adoption."), l("Un copiloto ahorra horas de trabajo, pero sus costos dependen de los tokens y de la cantidad de pasos ejecutados. ¿Cobrarías por usuario, por uso, por resultado o mediante un paquete?", "A copilot saves hours, but its costs depend on tokens and steps. Do you charge per seat, usage, outcome or bundle?"), l("Los usuarios intensivos obtienen más valor y también cuestan más; los compradores de grandes empresas exigen previsibilidad. Diseña una métrica de cobro y límites de uso claros.", "Intensive users get more value and cost more; enterprise buyers demand predictability. Design a metric and guardrails."), l("Supón que cobrar por uso reduce la experimentación de los clientes y limita el valor que llegan a descubrir. ¿Qué esquema combinado utilizarías?", "Assume usage pricing reduces customer experimentation and limits discovered value. Which hybrid architecture would you use?"), l("El costo crece con el uso, pero el cliente compra un resultado predecible. ¿Qué debe equilibrar el precio?", "Cost scales with usage, but the customer buys a predictable outcome. What must pricing balance?"), l("Debe equilibrar valor, costo y previsibilidad mediante paquetes, límites o planes que no castiguen el uso valioso.", "Value, cost and predictability through packages, limits or tiers that do not punish useful adoption."), { "es-CL": ["precio", "valor", "uso", "costo", "previsibilidad"], en: ["price", "value", "usage", "cost", "predictability"] }),
  skill("ai-capability-feature-product", l("Agregar una función visible de IA no la convierte en un producto ni crea por sí sola una propuesta de valor sostenible.", "Adding visible AI does not turn a feature into a product or create a sustainable value proposition."), l("Una capacidad se convierte en producto cuando resuelve un resultado completo, tiene usuarios y una economía propios, cuenta con distribución y mejora a partir del uso.", "A capability becomes a product when it solves a complete outcome, has its own user and economics, distribution and a learning system."), l("Una función puede ser estratégica sin justificar un producto separado; ofrecerla aparte puede fragmentar el flujo de trabajo y dificultar la adopción.", "A feature can be strategic without justifying a separate product; packaging it separately can fragment workflow and adoption."), l("Una empresa crea resúmenes excelentes dentro de su plataforma y quiere venderlos como un producto independiente. ¿Qué probarías primero?", "A company builds excellent summaries inside its platform and wants to sell them as a standalone product. What would you test first?"), l("La función ahorra tiempo dentro de un flujo existente, pero fuera de él no tiene un comprador, un canal de distribución ni una tarea completa que resolver.", "The feature saves time inside an existing workflow but has no buyer, distribution or complete job outside it."), l("Supón que los competidores incorporan gratuitamente la misma capacidad. ¿Qué parte de la propuesta sigue constituyendo un producto?", "Assume competitors include the same capability for free. Which part of the proposition remains a product?"), l("Una capacidad valiosa carece de un flujo de trabajo, un comprador y un canal propios. ¿Qué es hoy?", "A valuable capability lacks its own workflow, buyer and channel. What is it today?"), l("Es una función dentro de un producto, hasta que demuestre que resuelve un resultado completo y que puede capturar valor por sí misma.", "A feature within a product until it proves a complete outcome and value-capture architecture."), { "es-CL": ["producto", "función", "resultado", "flujo", "valor"], en: ["product", "feature", "outcome", "workflow", "value"] }),
  skill("ai-model-commoditization", l("Que varios modelos obtengan resultados similares en pruebas comparativas no significa que todos los productos pierdan su diferenciación.", "Model convergence on benchmarks does not mean every product loses differentiation."), l("Cuando la capa base se estandariza, la ventaja se desplaza hacia la distribución, los datos, los flujos de trabajo, las evaluaciones, la confianza y la velocidad de aprendizaje.", "When the base layer commoditizes, advantage migrates toward distribution, data, workflow, evaluations, trust and learning speed."), l("Una capa diferenciadora puede convertirse mañana en algo estándar. La estrategia debe identificar qué mecanismo seguirá acumulando valor con el tiempo.", "A differentiating layer today can become standard tomorrow; strategy must identify which mechanism compounds value over time."), l("Tu producto gana gracias a un modelo exclusivo, pero las alternativas abiertas ya alcanzan el mismo desempeño. ¿Qué deberías reevaluar?", "Your product wins by using an exclusive model whose performance is now matched by open alternatives. What must you reassess?"), l("La empresa tiene un canal propio, datos de interacción y evaluaciones internas, pero el modelo se vuelve intercambiable. Identifica dónde permanece la ventaja.", "The company owns channel, interaction data and evaluations while the model becomes interchangeable. Locate the remaining advantage."), l("Supón que cambiar de modelo toma un día. ¿Qué activo sigue mejorando el producto después de cada sustitución?", "Assume switching models takes one day. Which asset still makes the product better after every switch?"), l("La calidad de los modelos se iguala, pero uno de los productos mejora más rápido con el uso real. ¿Dónde está su defensa competitiva?", "Model quality equalizes, but one product improves faster through real usage. Where is defensibility?"), l("En el sistema de aprendizaje, los datos, la distribución y el flujo de trabajo que acumulan ventaja sobre una base tecnológica sustituible.", "In the learning system, data, distribution and workflow that compound advantage over substitutable models."), { "es-CL": ["estandar", "distribución", "datos", "flujo", "evaluación"], en: ["commodit", "distribution", "data", "workflow", "evaluation"] }),
  skill("ai-distribution-advantage", l("Un producto superior no gana automáticamente si no está presente en el flujo de trabajo ni en el momento en que el usuario decide, o si no genera suficiente confianza.", "A superior product does not automatically win if it does not reach the user's workflow, trust or decision moment."), l("La distribución es la capacidad de llegar al usuario de forma repetible y económicamente sostenible, mediante presencia, integraciones, marca o una red comercial.", "Distribution is repeatable, economically defensible access to the user, reinforced by presence, integration, brand or sales reach."), l("La distribución sin valor sólo acelera la prueba y el abandono. La ventaja aparece cuando el acceso se convierte en uso recurrente y aprendizaje.", "Distribution without value only accelerates trial and churn; its advantage depends on turning access into use and learning."), l("Una empresa emergente tiene un copiloto mejor, pero la empresa establecida puede activarlo mañana para un millón de usuarios. ¿Qué compararías?", "A startup has a better copilot, but the incumbent can activate one million users tomorrow. What would you compare?"), l("La empresa emergente mejora rápido gracias a usuarios intensivos; la empresa establecida dispone de canal, confianza y un flujo de trabajo ya instalado. Evalúa cuál convierte mejor el acceso en aprendizaje.", "The startup improves quickly with intensive users; the incumbent has channel, trust and installed workflow. Evaluate conversion of access into learning."), l("Supón que las interfaces abiertas y las plataformas de distribución neutralizan el canal de la empresa establecida. ¿Qué ventaja permanece?", "Assume APIs and marketplaces neutralize the incumbent's channel. Which distribution advantage remains?"), l("Una empresa establecida llega a todos, pero pocos adoptan su solución; una empresa emergente llega a pocos y retiene a casi todos. ¿Cuál tiene ventaja?", "An incumbent reaches everyone but few adopt; a startup reaches few and retains almost all. Who has advantage?"), l("Depende de cuál convierta el acceso en uso recurrente con una economía escalable; el alcance por sí solo no decide.", "It depends on who converts access into repeated use with scalable economics; reach alone does not decide."), { "es-CL": ["distribución", "acceso", "adopción", "flujo", "canal"], en: ["distribution", "access", "adoption", "workflow", "channel"] }),
  skill("ai-data-advantage", l("Tener muchos datos no crea una ventaja si no mejoran una decisión, si otros pueden obtenerlos o si no generan retroalimentación útil.", "Having lots of data creates no advantage when it does not improve a decision, is not exclusive or produces no useful feedback."), l("Una ventaja de datos requiere un acceso diferencial, una relación demostrable con el desempeño y un ciclo en el que el uso mejora el sistema y atrae más uso.", "A data advantage requires differentiated access, causal connection to performance and a loop where usage improves the system and attracts more usage."), l("Los datos históricos pueden perder relevancia cuando cambian el comportamiento, la tarea o la tecnología base.", "Historical data can lose relevance when behavior, task or base technology changes."), l("Una empresa posee diez años de solicitudes de soporte, pero el modelo no mejora al utilizarlas. ¿Qué hipótesis revisarías?", "A company owns ten years of tickets, but the model does not improve when they are included. Which hypotheses would you revisit?"), l("Hay abundancia de datos, pero las etiquetas son inconsistentes y faltan resultados observables para medir el impacto. Diseña el ciclo que falta.", "Data is abundant, but inconsistent labels and missing outcomes prevent impact evaluation. Design the missing loop."), l("Supón que un proveedor externo obtiene datos equivalentes de miles de clientes. ¿Qué haría realmente exclusivos a los tuyos?", "Assume an external vendor gets equivalent data from thousands of customers. What makes yours proprietary?"), l("Más datos no mejoran el resultado, pero la retroalimentación del uso sí permite corregir errores. ¿Dónde está la ventaja?", "More data does not improve outcomes, but usage feedback does correct errors. Where is the advantage?"), l("En el ciclo exclusivo que conecta la interacción con un resultado observable y una mejora medible, no en el volumen de datos por sí solo.", "In the exclusive loop connecting interaction, outcome and measurable improvement, not raw volume."), { "es-CL": ["datos", "retroalimentación", "resultado", "exclusiv", "mejora"], en: ["data", "feedback", "outcome", "exclusive", "improve"] }),
  skill("ai-copilot-agent", l("Un agente no es simplemente un asistente conversacional más capaz; la diferencia central es que tiene autoridad para actuar y completar procesos.", "An agent is not simply a more capable chatbot; the central difference is authority to act and close loops."), l("La autonomía adecuada depende del impacto, la reversibilidad, la capacidad de verificación y el costo de supervisar cada tarea.", "Appropriate autonomy depends on impact, reversibility, verifiability and supervision cost for each task."), l("Automatizar más pasos puede aumentar el valor y también ampliar los puntos de falla. La autonomía debe diseñarse para cada acción, no definirse mediante una etiqueta general del producto.", "Automating more steps can increase value and failure surface; autonomy must be designed by action, not product label."), l("Un asistente redacta reembolsos; el equipo quiere que también los ejecute. ¿Qué cambia en el diseño?", "An assistant drafts refunds; the team wants it to issue them too. What changes in the design?"), l("Los errores de redacción se pueden revisar; los pagos ejecutados afectan dinero y confianza. Define límites, aprobaciones y mecanismos de recuperación.", "Drafting errors are reviewable; executed payments affect money and trust. Define boundaries, approval and recovery."), l("Supón que todas las acciones pueden revertirse con un clic. ¿Cuánta autonomía adicional aceptarías y qué seguirías midiendo?", "Assume every action can be reversed in one click. How much additional autonomy would you accept and what would you still measure?"), l("Dos sistemas usan el mismo modelo; uno recomienda y el otro ejecuta pagos. ¿Cuál requiere más control?", "Two systems use the same model; one recommends and the other executes payments. Which requires more control?"), l("El sistema que actúa, porque el impacto, la autoridad y el costo del error cambian aunque el modelo sea idéntico.", "The acting system because impact, authority and error cost change even when the model is identical."), { "es-CL": ["autonomía", "acción", "reversib", "riesgo", "supervisión"], en: ["autonomy", "action", "reversib", "risk", "supervision"] }),
  skill("ai-human-loop", l("Agregar una aprobación humana en cada paso no garantiza seguridad y puede crear una supervisión meramente formal.", "Adding human approval at every step does not guarantee safety and can create superficial oversight."), l("La supervisión humana agrega valor cuando la persona dispone de contexto, autoridad, tiempo y una señal clara sobre la incertidumbre o el impacto.", "Humans add value when they have context, authority, time and a clear signal of uncertainty or impact."), l("Demasiadas alertas generan aprobaciones automáticas y superficiales; muy pocas esconden fallas. El sistema debe priorizar las excepciones realmente importantes.", "Too many alerts create rubber-stamping; too few hide failures. The loop must prioritize material exceptions."), l("Un analista aprueba 400 recomendaciones diarias en pocos segundos. ¿Existe realmente control humano?", "An analyst approves 400 recommendations daily in seconds. Is there meaningful human control?"), l("El sistema conoce el nivel de confianza, el monto involucrado y la reversibilidad de cada acción. Define cuándo automatizar, revisar o escalar.", "The system knows confidence, amount and irreversibility. Design when to automate, review or escalate."), l("Supón que la persona acepta 99% de las sugerencias sin leerlas. ¿Qué rediseñarías primero?", "Assume the human accepts 99% of suggestions without reading. What do you redesign first?"), l("Existe una revisión humana formal, pero nunca cambia una decisión. ¿Qué indica?", "Human review formally exists but changes no decisions. What does that indicate?"), l("Indica que la revisión no aporta criterio efectivo. Hay que rediseñar las señales, la carga y la autoridad, o eliminar una fricción que no agrega valor.", "That the loop adds no effective judgment; signals, load, authority or empty friction must be redesigned."), { "es-CL": ["humano", "revisión", "escal", "incertidumbre", "impacto"], en: ["human", "review", "escal", "uncertainty", "impact"] }),
  skill("ai-trust-control", l("Confianza no significa que el usuario crea siempre en la IA; significa que sabe cuándo apoyarse, verificar o detenerla.", "Trust does not mean users always believe AI; it means they know when to rely, verify or stop it."), l("La confianza calibrada surge de límites visibles, evidencia, control proporcional y recuperación clara ante fallas.", "Calibrated trust comes from visible boundaries, evidence, proportional control and clear failure recovery."), l("Explicar demasiado puede simular certeza o sobrecargar; control útil depende del riesgo y del momento de decisión.", "Over-explaining can simulate certainty or overload; useful control depends on risk and decision moment."), l("Usuarios ignoran un copiloto porque no saben de dónde salen sus recomendaciones. ¿Qué control probarías antes de añadir más texto?", "Users ignore a copilot because they do not know where recommendations come from. Which control would you test before adding more text?"), l("La recomendación usa fuentes internas, tiene confianza variable y algunas acciones son reversibles. Diseña visibilidad y autoridad por nivel.", "The recommendation uses internal sources, has variable confidence and some actions are reversible. Design visibility and authority by level."), l("Supón que mostrar una explicación larga reduce adopción sin mejorar detección de errores. ¿Qué alternativa usarías?", "Assume showing a long explanation lowers adoption without improving error detection. Which alternative would you use?"), l("Un sistema muestra alta confianza en una tarea donde no fue evaluado. ¿Qué debería comunicar la interfaz?", "A system shows high confidence on a task where it was not evaluated. What should the interface communicate?"), l("El límite de validez y una ruta de verificación o escalamiento, no una certeza fabricada.", "The validity boundary and a verification or escalation path, not fabricated certainty."), { "es-CL": ["confianza", "control", "límite", "verific", "recuper"], en: ["trust", "control", "boundary", "verify", "recover"] }),
  skill("ai-evaluation-design", l("Medir una precisión genérica desconecta la evaluación del producto, del riesgo y de la decisión de lanzamiento.", "Measuring generic accuracy disconnects evaluation from product, risk and launch decisions."), l("Un sistema de evaluación traduce resultados, segmentos y tipos de falla en conjuntos de datos, métricas, umbrales y pruebas de regresión.", "An eval system translates outcomes, segments and failures into datasets, metrics, thresholds and regression cycles."), l("Optimizar contra un conjunto fijo puede enseñar al sistema a aprobar la prueba sin mejorar su desempeño en el mundo real.", "Optimizing against a fixed set can teach the system to pass the test without improving the real world."), l("Un equipo obtiene 92% de precisión, pero no sabe si debería lanzar el producto. ¿Qué falta en su diseño de evaluación?", "A team has 92% accuracy but cannot decide whether to launch. What is missing from its evaluation design?"), l("Los errores tienen impactos distintos según el segmento y algunos aparecen sólo después de cambiar las instrucciones. Diseña criterios de aprobación y monitoreo.", "Errors have different impacts by segment and some appear only after prompt changes. Design gates and monitoring."), l("Supón que el modelo supera las pruebas internas, pero los usuarios corrigen 30% de sus resultados. ¿Qué evidencia incorporarías?", "Assume the model passes the offline set but users correct 30% of outputs. Which evidence do you incorporate?"), l("Un puntaje mejora mientras el resultado real del flujo de trabajo no cambia. ¿Qué deberías revisar?", "A score rises while the workflow outcome does not change. What must be reviewed?"), l("La validez de la métrica y del conjunto de datos frente al resultado real que la evaluación busca proteger.", "The validity of the metric and dataset relative to the real outcome the evaluation is meant to protect."), { "es-CL": ["evaluación", "resultado", "umbral", "datos", "regresión"], en: ["eval", "outcome", "threshold", "dataset", "regression"] }),
  skill("agent-workflow-decomposition", l("Entregar un objetivo amplio a un agente oculta los estados, las dependencias y los puntos donde una falla podría propagarse.", "Giving an agent a broad goal hides states, dependencies and points where failure propagates."), l("Descomponer el flujo de trabajo hace explícitas las entradas, los resultados esperados, las herramientas, los puntos de control y los criterios para completar cada etapa.", "Workflow decomposition makes inputs, outputs, tools, checkpoints and completion criteria explicit by stage."), l("Demasiados pasos aumentan la latencia y la coordinación; muy pocos reducen la visibilidad y la capacidad de recuperación.", "Too many steps raise latency and coordination; too few reduce observability and recoverability."), l("Un agente debe investigar, cotizar, aprobar y comprar sin puntos de control intermedios. ¿Cómo dividirías el flujo?", "An agent must research, quote, approve and purchase without checkpoints. How would you divide the workflow?"), l("Algunas etapas son reversibles y otras comprometen dinero. Define el estado, la evidencia y la autoridad necesarias antes de cada transición.", "Some stages are reversible and others commit money. Define state, evidence and authority before each transition."), l("Supón que la investigación falla sin generar una alerta, pero la compra continúa. ¿Qué condición entre etapas faltó?", "Assume research fails silently but purchasing continues. Which contract between stages was missing?"), l("El flujo termina, pero no puedes saber qué fuente produjo la decisión final. ¿Qué faltó?", "A workflow completes, but you cannot tell which source produced the final decision. What was missing?"), l("Estados y trazabilidad explícitos entre pasos, con resultados verificables antes de avanzar.", "Explicit state and traceability between steps, with verifiable outputs before advancing."), { "es-CL": ["flujo", "estado", "control", "resultado", "trazabilidad"], en: ["workflow", "state", "checkpoint", "output", "trace"] }),
  skill("agent-autonomy", l("Más autonomía no siempre significa más valor: el costo de los errores y la dificultad de supervisión pueden crecer más rápido que la productividad.", "More autonomy does not always mean more value; error cost and supervision difficulty can rise faster than productivity."), l("La autonomía debe definirse para cada acción según su impacto, reversibilidad, visibilidad, incertidumbre y velocidad de retroalimentación.", "Autonomy is assigned by action according to impact, reversibility, observability, uncertainty and feedback speed."), l("Un agente puede actuar libremente en tareas de bajo riesgo y, al mismo tiempo, requerir autorización humana para un único paso irreversible.", "An agent can operate freely on low-risk tasks and require human authority for one irreversible step."), l("Un agente de ventas puede redactar mensajes, otorgar descuentos y firmar renovaciones. ¿Qué nivel de autonomía darías a cada acción?", "A sales agent can draft, send discounts and sign renewals. Which autonomy would you give each action?"), l("Los errores de redacción se pueden corregir; los descuentos afectan el margen y los contratos crean obligaciones. Diseña un nivel de autonomía distinto para cada acción.", "Text errors are recoverable; discounts affect margin and contracts create obligations. Design separate levels."), l("Supón que el sistema aprende rápidamente de sus errores, pero una sola falla puede causar un daño regulatorio. ¿Qué debería limitar su autonomía?", "Assume the system learns quickly from errors, but one failure can cause regulatory harm. What limits autonomy?"), l("Una tarea tiene una tasa de éxito de 98%, pero una sola falla sería irreversible y muy costosa. ¿Debería automatizarse por completo?", "A task has 98% success and one very costly irreversible failure. Should it be fully automated?"), l("No basta con la tasa promedio: el impacto, la reversibilidad y la capacidad de detectar fallas deben definir la autoridad del sistema.", "Not from average success alone; impact, reversibility and detection must define authority."), { "es-CL": ["autonomía", "impacto", "reversib", "visibilidad", "autoridad"], en: ["autonomy", "impact", "reversib", "observability", "authority"] }),
];

const byId = new Map(expandedSkills.map((item) => [item.id, item]));
export function getExpandedSkill(id: string) { return byId.get(id); }
export function isExpandedSkill(id: string) { return byId.has(id); }
export function expandedSkillText(skill: ExpandedSkill, locale: Locale) { return { misconception: skill.misconception[locale], principle: skill.principle[locale], boundary: skill.boundary[locale], diagnosticScenario: skill.diagnosticScenario[locale], applicationScenario: skill.applicationScenario[locale], counterfactual: skill.counterfactual[locale], transferScenario: skill.transferScenario[locale], transferCorrect: skill.transferCorrect[locale] }; }
